def canon(s):
    pts=list(s); forms=[]
    for reflect in [False,True]:
      for rot in range(4):
       q=[]
       for x,y in pts:
        if reflect: y=-y
        for _ in range(rot): x,y=y,-x
        q.append((x,y))
       minx=min(x for x,y in q); miny=min(y for x,y in q)
       forms.append(tuple(sorted((x-minx,y-miny) for x,y in q)))
    return min(forms)
